-- Kivelle Content Pack 1. Existing City Life records remain canonical; this adds
-- reusable authored situations, story graphs, variable dates, trips, and media hooks.

alter table public.together_event_templates
  add column if not exists category text not null default 'ordinary',
  add column if not exists tone text not null default 'mundane',
  add column if not exists scale text not null default 'normal',
  add column if not exists content_level text not null default 'standard',
  add column if not exists conditions jsonb not null default '{}'::jsonb,
  add column if not exists followups text[] not null default '{}';

alter table public.together_event_templates
  add constraint together_event_templates_category_check check(category in ('ordinary','work','social','relationship','family','personal','discovery','celebration','conflict','opportunity','setback','health','weather','world','romance','intimacy','travel')) not valid,
  add constraint together_event_templates_tone_check check(tone in ('mundane','funny','positive','awkward','stressful','exciting','romantic','emotional','surprising')) not valid,
  add constraint together_event_templates_scale_check check(scale in ('micro','normal','meaningful','major')) not valid,
  add constraint together_event_templates_content_level_check check(content_level in ('standard','romance','mature','explicit')) not valid;
alter table public.together_event_templates validate constraint together_event_templates_category_check;
alter table public.together_event_templates validate constraint together_event_templates_tone_check;
alter table public.together_event_templates validate constraint together_event_templates_scale_check;
alter table public.together_event_templates validate constraint together_event_templates_content_level_check;

create table if not exists public.together_story_arc_templates(
  slug text primary key,title text not null,category text not null,eligible_template_ids uuid[] not null default '{}',
  min_relationship_stage text,prerequisites jsonb not null default '{}'::jsonb,chapters jsonb not null,
  cooldown_days integer not null default 14 check(cooldown_days between 1 and 365),repeatable boolean not null default false,
  priority text not null default 'minor' check(priority in ('minor','major')),active boolean not null default true,
  created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table if not exists public.together_story_arc_instances(
  id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,
  character_instance_id uuid not null references public.together_character_instances(id) on delete cascade,
  template_slug text not null references public.together_story_arc_templates(slug) on delete restrict,
  current_chapter_id text not null,status text not null default 'active' check(status in ('active','paused','completed','cancelled')),
  priority text not null check(priority in ('minor','major')),next_eligible_at timestamptz,state jsonb not null default '{}'::jsonb,
  started_at timestamptz not null default now(),completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
  unique(user_id,character_instance_id,template_slug)
);
alter table public.together_life_events add column if not exists story_arc_instance_id uuid references public.together_story_arc_instances(id) on delete set null;
create index if not exists together_story_arc_instances_user_character_idx on public.together_story_arc_instances(user_id,character_instance_id,status,next_eligible_at);

create table if not exists public.together_trip_templates(
  slug text primary key,title text not null,description text not null,min_relationship_stage text not null,
  duration_days smallint not null check(duration_days between 1 and 14),locations jsonb not null,itinerary jsonb not null,
  content_level text not null default 'romance' check(content_level in ('standard','romance','mature','explicit')),
  active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table if not exists public.together_photo_opportunities(
  slug text primary key,title text not null,trigger_event_category text,location_tags text[] not null default '{}',
  relationship_stages text[] not null default '{}',content_level text not null default 'standard' check(content_level in ('standard','romance','mature','explicit')),
  shot_type text not null check(shot_type in ('selfie','portrait','candid','scene')),prompt_seed text not null,metadata jsonb not null default '{}'::jsonb,
  active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table if not exists public.together_content_usage(
  id bigint generated always as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,
  character_instance_id uuid not null references public.together_character_instances(id) on delete cascade,
  content_kind text not null check(content_kind in ('event','arc','date','trip','photo','proactive')),
  content_key text not null,used_at timestamptz not null default now(),metadata jsonb not null default '{}'::jsonb
);
create index if not exists together_content_usage_recent_idx on public.together_content_usage(user_id,character_instance_id,content_kind,used_at desc);

alter table public.together_date_sessions drop constraint if exists together_date_sessions_current_phase_check;
alter table public.together_date_sessions drop constraint if exists together_date_sessions_phase_index_check;
alter table public.together_date_sessions add constraint together_date_sessions_phase_index_nonnegative check(phase_index >= 0) not valid;
alter table public.together_date_sessions validate constraint together_date_sessions_phase_index_nonnegative;

alter table public.together_story_arc_templates enable row level security;
alter table public.together_story_arc_instances enable row level security;
alter table public.together_trip_templates enable row level security;
alter table public.together_photo_opportunities enable row level security;
alter table public.together_content_usage enable row level security;
create policy "Published story arcs are readable" on public.together_story_arc_templates for select using (active);
create policy "Users read their story arcs" on public.together_story_arc_instances for select using (auth.uid()=user_id);
create policy "Users read their content usage" on public.together_content_usage for select using (auth.uid()=user_id);
create policy "Published trips are readable" on public.together_trip_templates for select using (active);
create policy "Published photo hooks are readable" on public.together_photo_opportunities for select using (active);

