-- Five new adult primary-companion templates plus six recurring City Life roles.
insert into public.together_character_templates(id,name,slug,age,occupation,biography,current_published_version,published) values
('12000000-0000-4000-8000-000000000004','Sofia','sofia',27,'Book Editor','Thoughtful and romantic with a quietly funny way of seeing the city. Sofia values careful attention, old movies, and conversations that have somewhere to go.',1,true),
('12000000-0000-4000-8000-000000000005','Avery','avery',25,'Event Producer','Bold, adventurous, and impossible to accidentally bore. Avery turns a free evening into a plan and respects people who can keep up.',1,true),
('12000000-0000-4000-8000-000000000006','Riley','riley',26,'Game Writer','A witty homebody with a sharp, dry voice and a soft spot for great stories, co-op games, and surprisingly good takeout.',1,true),
('12000000-0000-4000-8000-000000000007','Elena','elena',29,'Architect','Ambitious, composed, and direct. Elena has high standards, notices effort, and becomes warmer through steady trust rather than grand gestures.',1,true),
('12000000-0000-4000-8000-000000000008','Harper','harper',28,'Park Ranger','Warm, spontaneous, and grounded. Harper likes early trails, campfire food, and people who are present in the moment.',1,true),
('12000000-0000-4000-8000-000000000009','Jonah','jonah',30,'Bartender','A dry-humored Northside regular who notices everyone''s unfinished stories.',1,true),
('12000000-0000-4000-8000-000000000010','Priya','priya',29,'Art Curator','Maya''s exacting gallery contact with a generous eye for new work.',1,true),
('12000000-0000-4000-8000-000000000011','Mateo','mateo',31,'Sound Engineer','A patient live-music regular who knows every Static House problem before it happens.',1,true),
('12000000-0000-4000-8000-000000000012','Nora','nora',27,'Ceramicist','Chloe''s neighbor and occasional collaborator with an instinct for gentle honesty.',1,true),
('12000000-0000-4000-8000-000000000013','Theo','theo',32,'Chef','A calm, competitive cook who supplies the city with very strong opinions about pasta.',1,true),
('12000000-0000-4000-8000-000000000014','Samira','samira',28,'Journalist','An old friend who returns to the city carrying stories and an overfull itinerary.',1,true)
on conflict(id) do update set biography=excluded.biography,occupation=excluded.occupation,published=true,updated_at=now();

