insert into public.together_event_templates(id,name,event_type,category,tone,scale,content_level,world_id,default_location_id,participant_template_ids,significance,probability,duration_minutes,narrative_summary,state_effects,conditions,followups,user_visibility,proactive_eligible,metadata,active)
select gen_random_uuid(), situation.title || ' · ' || character.name, situation.category, situation.category, situation.tone, situation.scale, case when situation.category='romance' then 'romance' else 'standard' end, '10000000-0000-4000-8000-000000000001'::uuid, location.id, array[character.id], situation.significance, situation.probability, situation.duration_minutes, situation.narrative, jsonb_build_object('mood',jsonb_build_object(case when situation.tone in ('stressful','awkward') then 'thoughtful' else 'content' end,1)), jsonb_build_object('location_tags',array['city',coalesce(location.category,'city')]), array[]::text[], case when situation.scale in ('meaningful','major') then 'contextual' else 'hidden' end, situation.proactive, jsonb_build_object('display_title',situation.title,'narrative_seed',situation.narrative,'location_tags',array['city',coalesce(location.category,'city')]), true
from situation cross join primary_characters character left join public.together_locations location on location.slug=situation.location_slug
on conflict(name) do update set category=excluded.category,tone=excluded.tone,scale=excluded.scale,content_level=excluded.content_level,default_location_id=excluded.default_location_id,significance=excluded.significance,probability=excluded.probability,narrative_summary=excluded.narrative_summary,state_effects=excluded.state_effects,conditions=excluded.conditions,metadata=excluded.metadata,active=true,updated_at=now();

