('Editing backlog','work','stressful','normal','photography-studio',.48,.10,'An editing backlog made Maya reconsider every promise she made this week.',false,'creative-burnout'),
('Client loves the work','work','positive','meaningful','photography-studio',.70,.08,'A client sent the kind of note Maya saves instead of merely reading.',true,'big-client'),
('Bad lighting rescue','work','stressful','normal','photography-studio',.50,.09,'A lighting problem nearly sank a shoot before Maya improvised a solution.',false,null),
('Unexpected referral','opportunity','surprising','meaningful','photography-studio',.66,.06,'A former client passed Maya''s name to someone with a project she actually wants.',true,'career-crossroads'),
('Portfolio refresh','work','positive','normal','maya-apartment',.44,.08,'Maya spent the evening revisiting work that no longer feels like the same version of her.',false,'gallery-opportunity'),
('Photographer reaches out','opportunity','surprising','meaningful','glassline-gallery',.68,.04,'A photographer Maya admires sent a short, unexpectedly encouraging message.',true,'photography-competition'),
('Creative disagreement','conflict','awkward','normal','photography-studio',.52,.06,'A collaborator pushed for a direction Maya does not believe in.',false,'big-client'),
('Outdoor shoot washed out','weather','stressful','normal','halcyon-park',.50,.08,'Rain washed out an outdoor shoot and forced a very fast backup plan.',false,'bad-week'),
('Perfect photo session','work','positive','meaningful','lark-botanical-garden',.74,.07,'A photo session clicked in the rare way that makes every difficult day worth it.',true,'photography-competition'),
('Chloe needs advice','social','emotional','normal','juniper-cafe',.48,.09,'Chloe called Maya for advice and arrived with a story that kept changing shape.',false,'chloe-needs-help'),
('Chloe terrible date','social','funny','meaningful','velvet-hour',.62,.06,'Chloe recounted a truly terrible date with the dramatic precision it deserved.',true,'chloe-new-relationship'),
('Alex project invitation','social','exciting','normal','photography-studio',.52,.07,'Alex asked Maya to help shape a small creative project with an unexpectedly good premise.',true,'alex-creative-project'),
('Old photo discovery','personal','emotional','meaningful','maya-apartment',.60,.06,'Maya found an old photo that made a past version of the city feel unexpectedly close.',true,'old-flame'),
('Apartment maintenance problem','setback','awkward','normal','maya-apartment',.43,.08,'A small apartment problem became a larger apartment problem by dinner.',false,'new-apartment-idea'),
('Quiet night requested','health','emotional','normal','maya-apartment',.45,.08,'Maya cleared an evening because she needed the quiet more than another plan.',false,'creative-burnout'),
('Upcoming date thought','relationship','romantic','normal','juniper-cafe',.54,.06,'Maya caught herself thinking about an upcoming plan with the user and smiled at the timing.',true,null),
('Saved photo to share','relationship','positive','normal','riverwalk',.52,.08,'Maya saved a photo because it felt like something the user would understand.',true,null),
('User memory changes choice','relationship','surprising','normal','common-market',.50,.06,'Something Maya remembered about the user changed a small choice she made that day.',true,null),
('Financial equipment expense','setback','stressful','meaningful','photography-studio',.64,.05,'A necessary equipment expense arrived at exactly the wrong time.',true,'financial-stress')
)
insert into public.together_event_templates(id,name,event_type,category,tone,scale,content_level,world_id,default_location_id,participant_template_ids,significance,probability,duration_minutes,narrative_summary,state_effects,conditions,followups,user_visibility,proactive_eligible,metadata,active)
select gen_random_uuid(), 'Maya · '||maya.title, maya.category, maya.category,maya.tone,maya.scale,'romance','10000000-0000-4000-8000-000000000001'::uuid,location.id,array['12000000-0000-4000-8000-000000000001'::uuid],maya.significance,maya.probability,case when maya.scale='major' then 120 else 70 end,maya.narrative,jsonb_build_object('mood',jsonb_build_object(case when maya.tone='stressful' then 'stressed' when maya.tone='exciting' then 'energized' else 'thoughtful' end,1)),jsonb_build_object('maxConflict',55),array[coalesce(maya.arc_slug,'')],case when maya.scale in ('meaningful','major') then 'visible' else 'contextual' end,maya.proactive,jsonb_build_object('display_title',maya.title,'story_arc_slug',maya.arc_slug,'narrative_seed',maya.narrative,'photo_opportunity',case when maya.category in ('work','relationship','opportunity') then 'city-life-candid' else null end),true
from maya left join public.together_locations location on location.slug=maya.location_slug
on conflict(name) do update set category=excluded.category,tone=excluded.tone,scale=excluded.scale,default_location_id=excluded.default_location_id,significance=excluded.significance,probability=excluded.probability,narrative_summary=excluded.narrative_summary,metadata=excluded.metadata,active=true,updated_at=now();

