('15000000-0000-4000-8000-000000000008','Gallery Afternoon','gallery-afternoon','10000000-0000-4000-8000-000000000001','11000000-0000-4000-8000-000000000018','An art-filled afternoon that lets Maya show you how she sees images.','maya-portrait','[{"id":"entry","title":"At the gallery","choices":[{"id":"ask-favorite","label":"Ask her favorite piece"},{"id":"share-first-impression","label":"Share your first impression"}]},{"id":"rooms","title":"The rooms","choices":[{"id":"ask-craft","label":"Ask about craft"},{"id":"tell-story","label":"Tell a story"}]},{"id":"after","title":"Afterward","choices":[{"id":"coffee-after","label":"Get coffee"},{"id":"stay-longer","label":"Stay longer"}]},{"id":"resolution","title":"A different way of looking","choices":[]}]','{"trust":22,"familiarity":26,"allowed_stages":["friend","flirting","dating"]}','gallery_afternoon',true),
('15000000-0000-4000-8000-000000000009','Bookstore + Coffee','bookstore-coffee','10000000-0000-4000-8000-000000000001','11000000-0000-4000-8000-000000000019','A quiet browse that turns into trading recommendations.','maya-portrait','[{"id":"browse","title":"Browse","choices":[{"id":"pick-for-her","label":"Pick a book for her"},{"id":"ask-recommendation","label":"Ask for one"}]},{"id":"notes","title":"Marginal notes","choices":[{"id":"share-favorite","label":"Share a favorite"},{"id":"ask-childhood","label":"Ask about childhood reading"}]},{"id":"coffee","title":"Coffee after","choices":[{"id":"make-callback","label":"Make a callback"},{"id":"sit-quietly","label":"Sit quietly"}]},{"id":"resolution","title":"A page to keep","choices":[]}]','{"familiarity":20,"allowed_stages":["friend","flirting","dating"]}','bookstore_coffee',true),
('15000000-0000-4000-8000-000000000010','Stay-In Movie Night','stay-in-movie-night','10000000-0000-4000-8000-000000000001','11000000-0000-4000-8000-000000000002','A quiet at-home movie night shaped by the conversation between scenes.','maya-portrait','[{"id":"choose-film","title":"Choose a film","choices":[{"id":"pick-horror","label":"Pick horror"},{"id":"pick-classic","label":"Pick a classic"}]},{"id":"settle-in","title":"Settle in","choices":[{"id":"make-popcorn","label":"Make popcorn"},{"id":"share-blanket","label":"Share a blanket"}]},{"id":"pause","title":"Pause the movie","choices":[{"id":"talk-real","label":"Talk about something real"},{"id":"tease-scene","label":"Tease the scene"}]},{"id":"resolution","title":"The credits can wait","choices":[]}]','{"comfort":28,"allowed_stages":["dating","exclusive","long_term"]}','stay_in_movie',true),
('15000000-0000-4000-8000-000000000011','Spontaneous Night Out','spontaneous-night-out','10000000-0000-4000-8000-000000000001','11000000-0000-4000-8000-000000000011','A loose plan that becomes whatever the city gives you.','maya-portrait','[{"id":"text","title":"The text","choices":[{"id":"say-yes-fast","label":"Say yes immediately"},{"id":"suggest-place","label":"Suggest a place"}]},{"id":"first-stop","title":"First stop","choices":[{"id":"order-weird","label":"Order something weird"},{"id":"make-friends","label":"Make friends"}]},{"id":"turn","title":"A turn in the night","choices":[{"id":"go-karaoke","label":"Go karaoke"},{"id":"find-quiet","label":"Find somewhere quiet"}]},{"id":"resolution","title":"No plan, good story","choices":[]}]','{"attraction":28,"allowed_stages":["flirting","dating","exclusive"]}','spontaneous_night_out',true),
('15000000-0000-4000-8000-000000000012','Weekend Day Trip','weekend-day-trip','10000000-0000-4000-8000-000000000001','11000000-0000-4000-8000-000000000025','A day outside the usual city loop, built for shared discoveries.','maya-portrait','[{"id":"depart","title":"Depart","choices":[{"id":"bring-snacks","label":"Bring snacks"},{"id":"make-playlist","label":"Make a playlist"}]},{"id":"explore","title":"Explore","choices":[{"id":"take-photo","label":"Take a photo"},{"id":"follow-trail","label":"Follow a trail"}]},{"id":"lunch","title":"Lunch","choices":[{"id":"share-dessert","label":"Share dessert"},{"id":"ask-future","label":"Ask about the future"}]},{"id":"return","title":"The return","choices":[{"id":"extend-day","label":"Extend the day"},{"id":"quiet-ride","label":"Enjoy the quiet ride"}]},{"id":"resolution","title":"A little farther together","choices":[]}]','{"trust":30,"comfort":30,"allowed_stages":["dating","exclusive","long_term"]}','weekend_day_trip',true)
